referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const out = [];
  const walk = (n, names, before, after) => {
    if (n.kind === "suite") {
      const b = before.concat(n.before ?? []),
        a = (n.after ?? []).concat(after);
      for (const child of n.children) walk(child, names.concat(n.name), b, a);
    } else {
      for (const x of before) out.push("hook:" + x);
      if (n.delay !== undefined) out.push("wait:" + n.delay);
      out.push({
        name: names.concat(n.name).join(" / "),
        pass: JSON.stringify(n.actual) === JSON.stringify(n.expected),
      });
      for (const x of after) out.push("hook:" + x);
    }
  };
  for (const n of d) walk(n, [], [], []);
  return out;
}

